        const int MOD=1000000007;
        vector<int> dp(n+1);
        dp[0]=1;
        for(int base=1;;++base){
            int power=powerAtMost(base,x,n);
            if(power>n)break;
            for(int sum=n;sum>=power;--sum){
                dp[sum]+=dp[sum-power];
                if(dp[sum]>=MOD)dp[sum]-=MOD;
            }
        }
        return dp[n];
    }
};
